<div class="stat-grid"><div class="stat-card gold"><span>Pengajuan aktif</span><strong><?= count(array_filter($activities, function($a) { return $a['status_approval'] === 'Not Approved'; })) ?></strong><small>Menunggu review atasan</small></div><div class="stat-card"><span>Profil pegawai</span><strong><?= html_escape($employee['nik']) ?></strong><small><?= html_escape($employee['jabatan']) ?></small></div></div>
<div class="panel"><div class="panel-toolbar"><div><h2>Riwayat Aktivitas</h2><p>Pengajuan dengan status pending masih dapat diperbarui.</p></div><button class="btn btn-success" data-open-modal="activityModal">+ Tambah Data</button></div><div class="table-controls"><form><label class="rows-control">Tampilkan <select data-page-size aria-label="Jumlah baris per halaman"><option>10</option><option>25</option><option>50</option></select> baris</label><input type="search" name="q" value="<?= html_escape($this->input->get('q')) ?>" placeholder="Pencarian..."></form></div><div class="table-wrap"><table data-table><thead><tr><th>No</th><th>Tanggal</th><th>Jenis</th><th>Keterangan</th><th>Dokumen</th><th>Status</th><th>Catatan Reject</th><th>Aksi</th></tr></thead><tbody><?php foreach ($activities as $i => $item): ?><tr data-activity='<?= html_escape(json_encode($item), true) ?>'><td><?= $i + 1 ?></td><td data-sort="<?= $item['tanggal'] ?>"><?= date('d/m/Y', strtotime($item['tanggal'])) ?></td><td><b><?= html_escape($item['jenis']) ?></b><small class="table-subtext"><?= html_escape($item['sub_status']) ?></small></td><td class="description-cell"><?= nl2br(html_escape($item['kegiatan'])) ?></td><td><?php if ($item['dokumen']): ?><a class="file-link" target="_blank" href="<?= base_url('assets/uploads/' . $item['dokumen']) ?>">Lihat file ↗</a><?php else: ?><span class="muted">-</span><?php endif; ?></td><td><span class="badge <?= strtolower(str_replace(' ', '-', $item['status_approval'])) ?>"><?= html_escape($item['status_approval']) ?></span></td><td><?= $item['catatan_reject'] ? html_escape($item['catatan_reject']) : '<span class="muted">-</span>' ?></td><td><?php if ($item['status_approval'] === 'Not Approved'): ?><div class="action-stack"><button class="btn btn-info btn-small" data-edit-activity>Edit</button><a class="btn btn-danger btn-small" href="<?= base_url('aktivitas/hapus/' . $item['id']) ?>" data-confirm="Hapus pengajuan ini?">Hapus</a></div><?php else: ?><span class="locked">🔒 Terkunci</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><div class="table-footer" data-pagination></div></div>
<div class="modal-backdrop" id="activityModal" aria-hidden="true"><div class="modal modal-lg"><div class="modal-header"><div><p class="eyebrow">PENGAJUAN BARU</p><h2 data-modal-title>Tambah Aktivitas</h2></div><button class="icon-button" data-close-modal>&times;</button></div><form method="post" action="<?= site_url('aktivitas/simpan') ?>" enctype="multipart/form-data" data-activity-form><input type="hidden" name="id"><div class="modal-body"><div class="form-grid"><label>Tanggal<input type="date" name="tanggal" required></label><div class="form-wide"><span class="label-title">Jenis aktivitas</span><div class="radio-row"><label><input type="radio" name="jenis" value="On Duty" required> On Duty</label><label><input type="radio" name="jenis" value="Off Duty"> Off Duty</label><label><input type="radio" name="jenis" value="Perjalanan Dinas"> Perjalanan Dinas</label><label><input type="radio" name="jenis" value="Cuti"> Cuti</label></div></div><label class="form-wide">Sub kategori aktivitas<select name="sub_status" required data-sub-status><option value="">Pilih jenis terlebih dahulu</option></select></label><label class="form-wide">Kegiatan<textarea name="kegiatan" rows="5" placeholder="Jelaskan kegiatan atau tujuan perizinan Anda..." required></textarea></label><label class="form-wide upload-field" data-document-field>Upload Dokumen <small>(PDF, JPG, PNG - maksimal 4MB)</small><input type="file" name="dokumen" accept=".pdf,.jpg,.jpeg,.png"></label></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-close-modal>Batal</button><button class="btn btn-success" type="submit">Simpan Pengajuan</button></div></form></div></div>
